def transform(grid):
    # The top-left 3x3 is the unique mixed pattern with the task's output
    # structure: it is selected by the adjoining reference figure; extract it.
    # Read all nonzero 3x3 components by bounding boxes.
    R,C=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(R):
      for c in range(C):
        if grid[r][c] and (r,c) not in seen:
          stack=[(r,c)]; seen.add((r,c)); cells=[]
          while stack:
            y,x=stack.pop(); cells.append((y,x))
            for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
              q=(y+dy,x+dx)
              if 0<=q[0]<R and 0<=q[1]<C and grid[q[0]][q[1]] and q not in seen:
                seen.add(q); stack.append(q)
          comps.append(cells)
    # Output is the component with the largest area (the 3x3 exemplar pattern).
    cells=max(comps,key=len); y0=min(y for y,x in cells); y1=max(y for y,x in cells); x0=min(x for y,x in cells); x1=max(x for y,x in cells)
    return [row[x0:x1+1] for row in grid[y0:y1+1]]
